//! **Stage 6: a place is detailed inside the box the whole gave it**
//! (spec-0050).
//!
//! # Why the pieces here are cut out of the massing
//!
//! Every detail piece in this file is generated by **taking the cells the
//! derivation would have written inside that place's frame and shipping them as
//! a `.nbt`**. That is not a shortcut, it is the sharpest instrument available
//! for the property stage 6 has to hold: *detailing a place must not change
//! whether the map is walkable*. A piece cut from the massing makes the built
//! world byte-for-byte the massed world — so the whole stage-5 battery
//! runs over it unchanged, and if the fabric split were off by a single cell on
//! any face, the substituted world would differ from the massed one and
//! `DW0836`/`DW0837`/`DW0838` would say so.
//!
//! It also means every red below is produced by **perturbing a piece that was
//! green**, never by hand-authoring a broken one: the same discipline
//! `tests/blockout.rs` applies to the derivation, one layer out.
//!
//! The generator is fed by `delvec allocation` and nothing else — the frame, the
//! seams, the answering-face classes and the owed names all come from the
//! handing. So the file doubles as the demonstration that the handing is
//! *sufficient*: a piece written against it alone satisfies every gate.

mod common;

use std::collections::{BTreeMap, BTreeSet};
use std::path::{Path, PathBuf};

use delvec::compiler::blockout::{self, Perturb};
use delvec::compiler::detail::{self, Allocation};
use delvec::compiler::plan::Plan;
use delvec::compiler::registry::PrefabRegistry;
use delvewright_dsl::{Campaign, DSL_VERSION, NodeId, Severity};

// ---------------------------------------------------------------------------
// The fixture, and the pieces cut out of its massing
// ---------------------------------------------------------------------------

fn blockout_dir() -> PathBuf {
    common::repo_root().join("crates/delvec/tests/fixtures/blockout")
}

fn campaign_at(dir: &Path) -> Campaign {
    common::campaign_at(dir)
}

/// The whole map's massing as a cell map, replayed in write order exactly as the
/// world applies it — the derivation the build runs, so a bound place's frame is
/// left empty.
fn massing(c: &Campaign) -> BTreeMap<[i64; 3], String> {
    let mut reads = delvewright_dsl::metrics::Reads::new();
    let (placement, _) = blockout::derive(c, &mut reads).expect("a site-plan campaign has massing");
    let fills = placement.mass;
    let mut out: BTreeMap<[i64; 3], String> = BTreeMap::new();
    for f in &fills {
        let lo = [
            i64::from(f.from[0]),
            i64::from(f.from[1]),
            i64::from(f.from[2]),
        ];
        let hi = [i64::from(f.to[0]), i64::from(f.to[1]), i64::from(f.to[2])];
        for cell in blockout::cells_of(lo, hi) {
            if f.block == "minecraft:air" {
                out.remove(&cell);
            } else {
                out.insert(cell, f.block.clone());
            }
        }
    }
    out
}

/// [`massing`] with nothing bound: the cells the derivation writes in every
/// place, which is what a piece is cut out of.
fn unbound_massing(c: &Campaign) -> BTreeMap<[i64; 3], String> {
    let mut c = c.clone();
    c.detail_plan = None;
    massing(&c)
}

/// A place's cells, piece-local, with air stated rather than omitted — which is
/// what a real exported piece does, and what makes the substitution total.
///
/// **Plus its own light**, and that is not decoration: spec-0050 §3 takes a bound
/// frame out of the whole's fixture pass, because the whole hanging torches
/// inside a building somebody designed would be the whole writing inside a bound
/// frame. A bound place lights itself and the existing gate judges it — so a
/// piece cut from the massing alone is a dark room, `DW0210` says so, and the
/// repair is the one a real detail piece makes. Torches on a four-cell grid over
/// the walk plane, never inside a seam's own cells.
fn piece_cells(
    c: &Campaign,
    a: &Allocation,
    mass: &BTreeMap<[i64; 3], String>,
) -> Vec<([i32; 3], String)> {
    let _ = c;
    let in_a_seam = |p: [i64; 3]| {
        a.seams.iter().any(|s| {
            (0..3).all(|i| {
                p[i] >= s.cells[0][i].min(s.cells[1][i]) && p[i] <= s.cells[0][i].max(s.cells[1][i])
            })
        })
    };
    // The cells of the frame the place does not own (spec-0098 §2): a piece
    // holds `structure_void` there, which is what makes it a piece.
    let void = |p: [i64; 3]| {
        a.voids
            .iter()
            .any(|v| (0..3).all(|i| p[i] >= v.cells[0][i] && p[i] <= v.cells[1][i]))
    };
    let mut out = Vec::new();
    for x in 0..a.extent[0] {
        for y in 0..a.extent[1] {
            for z in 0..a.extent[2] {
                let world = [a.world_min[0] + x, a.world_min[1] + y, a.world_min[2] + z];
                if void([x, y, z]) {
                    out.push((
                        [x as i32, y as i32, z as i32],
                        "minecraft:structure_void".to_string(),
                    ));
                    continue;
                }
                let mut block = mass
                    .get(&world)
                    .cloned()
                    .unwrap_or_else(|| "minecraft:air".to_string());
                let lit_here = y == 1 && x % 4 == 1 && z % 4 == 1;
                if lit_here && block == "minecraft:air" && !in_a_seam([x, y, z]) {
                    block = "minecraft:torch".to_string();
                }
                out.push(([x as i32, y as i32, z as i32], block));
            }
        }
    }
    out
}

/// The first cell a body can stand in, in piece-local coordinates: own cell and
/// the one above clear, the one below solid. Scanned in a fixed order so two
/// runs choose the same cell.
fn standing_cell(a: &Allocation, cells: &[([i32; 3], String)]) -> [i32; 3] {
    let solid: std::collections::BTreeSet<[i32; 3]> = cells
        .iter()
        .filter(|(_, b)| b != "minecraft:air" && b != "minecraft:structure_void")
        .map(|(p, _)| *p)
        .collect();
    for y in a.datum_y as i32..a.extent[1] as i32 {
        for x in 0..a.extent[0] as i32 {
            for z in 0..a.extent[2] as i32 {
                if !solid.contains(&[x, y, z])
                    && !solid.contains(&[x, y + 1, z])
                    && solid.contains(&[x, y - 1, z])
                {
                    return [x, y, z];
                }
            }
        }
    }
    panic!("`{}` offers nowhere to stand", a.place);
}

/// Write the piece a place's allocation asks for, cut out of the massing.
///
/// Everything the metadata claims comes from the allocation: the size is the
/// frame's extent, one face per allocated seam at the cells and class the
/// handing named, and one point anchor standing in the piece's own declared
/// space.
fn write_piece(dir: &Path, id: &str, a: &Allocation, cells: &[([i32; 3], String)]) {
    std::fs::create_dir_all(dir).unwrap();
    let refs: Vec<([i32; 3], &str)> = cells.iter().map(|(p, b)| (*p, b.as_str())).collect();
    let size = [a.extent[0] as i32, a.extent[1] as i32, a.extent[2] as i32];
    std::fs::write(
        dir.join(format!("{id}.nbt")),
        common::structure_nbt(size, &refs),
    )
    .unwrap();
    let seat = standing_cell(a, cells);
    let faces: Vec<serde_json::Value> = a
        .seams
        .iter()
        .map(|s| {
            serde_json::json!({
                "space": "room",
                "class": s.answer_with[0],
                "dir": s.face,
                "opening": { "from": s.cells[0], "to": s.cells[1] },
            })
        })
        .collect();
    // An owed name is a place to stand — except a barred seam's gate region,
    // owed by the place that owns the seam's plane (spec-0098 §2): that is a
    // gate anchor over exactly the allocated cells, closed by the bar the
    // piece (cut from the massing) already ships there.
    let anchors: serde_json::Map<String, serde_json::Value> = a
        .owed_anchors
        .iter()
        .enumerate()
        .map(|(i, name)| {
            let gate = name
                .strip_prefix("anchor/seam-")
                .and_then(|stem| a.seams.iter().find(|s| s.edge == format!("edge/{stem}")));
            let value = match gate {
                Some(sm) => serde_json::json!({
                    "region": { "from": sm.cells[0], "to": sm.cells[1] },
                    "block": "minecraft:iron_bars",
                }),
                None => serde_json::json!({
                    "pos": seat,
                    "facing": "north",
                    "resolves_to": "space:room",
                }),
            };
            (format!("seat{i}"), value)
        })
        .collect();
    let meta = serde_json::json!({
        "prefab_id": format!("prefab/{id}"),
        "structure": {
            "file": format!("{id}.nbt"),
            "id": id,
            "size": size,
            "data_version": 4671,
            "generator": "crates/delvec/tests/detail.rs",
        },
        "anchors": anchors,
        "connectors": [],
        "lighting": { "profile": "lit", "measured_min_light": 8, "measured": "2026-08-21" },
        "license": {
            "source": "original",
            "spdx": "GPL-3.0-or-later",
            "note": "Test fixture.",
            "provenance": "Cut out of the derived massing by crates/delvec/tests/detail.rs."
        },
        "spatial_contract": {
            "entry": "room",
            "spaces": {
                "room": {
                    "envelope": "enclosed",
                    "boxes": [{ "from": [0, 1, 0], "to": [size[0] - 1, size[1] - 1, size[2] - 1] }],
                },
            },
            "no_body": {},
            "edges": [],
            "faces": faces,
        },
    });
    std::fs::write(
        dir.join(format!("{id}.json")),
        serde_json::to_string_pretty(&meta).unwrap() + "\n",
    )
    .unwrap();
    // A detail piece cut out of the derived massing stands in a site-plan world
    // whose party gets outdoors, so `DW0885` asks it which of its sides are
    // finished surface. These are free-standing boxes in a `void` world: every
    // side that has a block on it is one the player would see.
    common::declare_shown_faces(dir, id);
}

/// What a green stage-6 campaign looks like on disk.
struct Detailed {
    campaign: PathBuf,
    prefabs: PathBuf,
}

/// Materialise the blockout fixture with `nodes` bound to pieces cut from its own
/// massing.
fn detailed(root: &Path, nodes: &[&str]) -> Detailed {
    detailed_from(&blockout_dir(), root, nodes, &|_, _| None)
}

/// A piece cell's edit: the place, the piece-local cell, and the block to write
/// there instead of the one cut from the massing (or `None` to keep it).
type CellEdit<'a> = &'a dyn Fn(&str, [i64; 3]) -> Option<String>;

/// [`detailed`] over any campaign directory, each cut piece edited by `edit`.
fn detailed_from(src: &Path, root: &Path, nodes: &[&str], edit: CellEdit<'_>) -> Detailed {
    let campaign = root.join("campaign");
    let prefabs = root.join("prefabs");
    std::fs::create_dir_all(&prefabs).unwrap();
    common::copy_dir_all(src, &campaign);
    let c = campaign_at(&campaign);
    let mass = unbound_massing(&c);

    let mut details = Vec::new();
    for node in nodes {
        let id = node.split('/').nth(1).unwrap();
        let a = detail::allocation(&c, &NodeId((*node).to_string()))
            .unwrap_or_else(|| panic!("`{node}` is a place this map has"));
        let mut cells = piece_cells(&c, &a, &mass);
        for (p, b) in &mut cells {
            if let Some(nb) = edit(node, [i64::from(p[0]), i64::from(p[1]), i64::from(p[2])]) {
                *b = nb;
            }
        }
        write_piece(&prefabs, id, &a, &cells);
        let anchors: serde_json::Map<String, serde_json::Value> = a
            .owed_anchors
            .iter()
            .enumerate()
            .map(|(i, name)| (name.clone(), serde_json::json!(format!("seat{i}"))))
            .collect();
        details.push(serde_json::json!({
            "place": node,
            "piece": format!("prefab/{id}"),
            "anchors": anchors,
        }));
    }
    write_detail_plan(&campaign, &details);
    Detailed { campaign, prefabs }
}

fn write_detail_plan(dir: &Path, details: &[serde_json::Value]) {
    let doc = serde_json::json!({
        "campaign_id": "blockout",
        "content": {
            "palette": { "role/wall": "minecraft:stone_bricks", "role/floor": "minecraft:tuff" },
            "details": details,
        },
        "dsl_version": DSL_VERSION,
        "stage": "detail-plan",
    });
    std::fs::write(
        dir.join("detail-plan.json"),
        delvewright_dsl::to_canonical_string(&doc).unwrap(),
    )
    .unwrap();
}

/// Run the validation-tier detail checks over a materialised campaign.
fn check_at(d: &Detailed) -> (Vec<delvewright_dsl::Diagnostic>, detail::DetailBinding) {
    let c = campaign_at(&d.campaign);
    let reg = PrefabRegistry::load_dir(&d.prefabs).expect("the piece library loads");
    detail::check(&c, &reg)
}

fn codes(d: &[delvewright_dsl::Diagnostic]) -> Vec<String> {
    d.iter().map(|x| x.code.clone()).collect()
}

fn errors(d: &[delvewright_dsl::Diagnostic]) -> Vec<&delvewright_dsl::Diagnostic> {
    d.iter().filter(|x| x.severity == Severity::Error).collect()
}

/// Edit a bound piece's metadata in place.
fn patch_piece(d: &Detailed, id: &str, f: impl FnOnce(&mut serde_json::Value)) {
    common::patch_file(&d.prefabs.join(format!("{id}.json")), f);
}

fn patch_detail_plan(d: &Detailed, f: impl FnOnce(&mut serde_json::Value)) {
    common::patch_file(&d.campaign.join("detail-plan.json"), f);
}

/// Every place the blockout fixture declares, **read off the graph**.
///
/// It was a hand-written list of six, and a hand-written census of something
/// that grows is the shape `CLAUDE.md` warns about: the fixture gained a place
/// and the list did not, so `fully_detailed` quietly became false in the test
/// that exists to assert it is true. Derived, it cannot go stale, and a fixture
/// that gained a place gets it detailed for free.
fn every_place() -> Vec<String> {
    let c = campaign_at(&blockout_dir());
    c.layout_graph
        .as_ref()
        .expect("the blockout fixture carries a layout graph")
        .content
        .nodes
        .iter()
        .map(|n| n.id.0.clone())
        .collect()
}

// ---------------------------------------------------------------------------
// The green case, and what it binds
// ---------------------------------------------------------------------------

#[test]
fn a_bound_place_validates_and_states_its_binding() {
    let tmp = tempdir("green");
    let d = detailed(&tmp, &["node/exit"]);
    let (diags, binding) = check_at(&d);
    assert!(
        errors(&diags).is_empty(),
        "a piece cut from the massing satisfies every stage-6 gate: {:?}",
        codes(&diags)
    );
    assert_eq!(binding.rows, 1, "one row read");
    assert_eq!(binding.bound, 1, "and it bound a place");
    assert_eq!(binding.boxes, 7, "against the plan's seven boxes");
    assert_eq!(binding.measured, 1, "one piece measured against its frame");
    assert_eq!(binding.seams_required, 1, "`node/exit` has one seam");
    assert_eq!(binding.faces_examined, 1, "and the piece declares one face");
    assert_eq!(binding.owed, 1, "and owes one anchor name");
    assert!(
        binding
            .line()
            .contains("1 of 7 place(s) bound over 1 `details[]` row(s)"),
        "the count states its denominator: {}",
        binding.line()
    );
}

/// A campaign that carries no detail plan runs every check zero times **and says
/// so** — the standing treatment for a binding of zero.
#[test]
fn a_campaign_with_no_detail_plan_binds_zero_and_states_it() {
    let c = campaign_at(&blockout_dir());
    let reg = PrefabRegistry::load_dir(&common::shown_prefabs_dir("detail")).unwrap();
    let (diags, binding) = detail::check(&c, &reg);
    assert!(diags.is_empty(), "{:?}", codes(&diags));
    assert_eq!(binding.rows, 0);
    assert!(
        binding
            .line()
            .contains("0 of 0 place(s) bound over 0 `details[]` row(s)"),
        "{}",
        binding.line()
    );
}

