#[test]
fn dw0842_refuses_an_anchor_key_the_place_does_not_owe() {
    let tmp = tempdir("dw0842-owe");
    let d = detailed(&tmp, &["node/exit"]);
    patch_detail_plan(&d, |v| {
        v["content"]["details"][0]["anchors"]["anchor/seam-cell-exit"] = serde_json::json!("seat0");
    });
    let e = check_and_expect(&d, "DW0842");
    assert!(e.contains("is not a name"), "{e}");
}

/// **One cause, one line — the primary-absent side.** With a map to be wrong
/// about, one bad `place` is one row's mistake: it is refused on its own, at its
/// own path, and the rows either side of it are not.
#[test]
fn dw0842_refuses_one_bad_row_per_row_while_the_map_exists() {
    let tmp = tempdir("dw0842-one-row");
    let places = every_place();
    let refs: Vec<&str> = places.iter().map(String::as_str).collect();
    let d = detailed(&tmp, &refs);
    patch_detail_plan(&d, |v| {
        v["content"]["details"][1]["place"] = serde_json::json!("node/nowhere");
    });
    let (diags, binding) = check_at(&d);
    let hit: Vec<_> = diags
        .iter()
        .filter(|x| x.code == "DW0842" && x.severity == Severity::Error)
        .collect();
    assert_eq!(
        hit.len(),
        1,
        "one wrong row is one refusal: {:?}",
        codes(&diags)
    );
    assert_eq!(hit[0].path, "/content/details[1]/place");
    assert!(
        hit[0].message.contains("node/nowhere"),
        "{}",
        hit[0].message
    );
    assert_eq!(
        binding.bound,
        places.len() - 1,
        "and every other row still bound"
    );
}

/// **One cause, one line — the primary-present side.** A site plan that resolves
/// ZERO boxes makes every `details[]` row miss by construction, so the per-row
/// refusal says one sentence once per row and none of the copies is the finding.
/// Measured on a 24-place campaign before this fold: `DW0824` (correct, one
/// line) followed by 24 copies of `DW0842`. The count, every row and the primary
/// it is downstream of are stated once — and the run still stops.
#[test]
fn dw0842_states_a_zero_box_plan_once_and_names_every_row() {
    let tmp = tempdir("dw0842-zero-boxes");
    let places = every_place();
    let refs: Vec<&str> = places.iter().map(String::as_str).collect();
    let d = detailed(&tmp, &refs);
    std::fs::remove_file(d.campaign.join("layout-graph.json")).unwrap();
    let (diags, binding) = check_at(&d);
    let hit: Vec<_> = diags
        .iter()
        .filter(|x| x.code == "DW0842" && x.severity == Severity::Error)
        .collect();
    assert_eq!(
        hit.len(),
        1,
        "one line for one map, not one per row: {:?}",
        codes(&diags)
    );
    assert_eq!(hit[0].path, "/content/details");
    for p in &places {
        assert!(
            hit[0].message.contains(p.as_str()),
            "a fold names every row it stands for; `{p}` is missing from: {}",
            hit[0].message
        );
    }
    assert!(
        hit[0].message.contains("DW0824"),
        "and it names the primary it defers to: {}",
        hit[0].message
    );
    assert_eq!(binding.rows, places.len(), "the row count is still stated");
    assert_eq!(binding.boxes, 0, "against a zero denominator");
    assert_eq!(binding.bound, 0);
}

/// The limiting case, named rather than inferred.
#[test]
fn dw0842_refuses_a_detail_plan_with_no_site_plan() {
    let tmp = tempdir("dw0842-nosite");
    let d = detailed(&tmp, &["node/exit"]);
    std::fs::remove_file(d.campaign.join("site-plan.json")).unwrap();
    let (diags, binding) = check_at(&d);
    let e = errors(&diags);
    assert!(e.iter().any(|x| x.code == "DW0842"), "{:?}", codes(&diags));
    assert_eq!(binding.boxes, 0, "and the zero denominator is stated");
}

/// **A row that is READ and a place that gets BOUND are different numbers**, and
/// collapsing them let the first exceed its own denominator.
///
/// Two rows naming one place: two rows read, one place bound, five boxes. Said
/// as one number it would have printed "2 of 5 place(s) bound" over a map with
/// one detailed place.
#[test]
fn a_row_read_and_a_place_bound_are_counted_apart() {
    let tmp = tempdir("counts");
    let d = detailed(&tmp, &["node/exit"]);
    patch_detail_plan(&d, |v| {
        let row = v["content"]["details"][0].clone();
        v["content"]["details"].as_array_mut().unwrap().push(row);
    });
    let (_, binding) = check_at(&d);
    assert_eq!(binding.rows, 2, "both rows were read");
    assert_eq!(binding.bound, 1, "and one place was bound");
    assert!(
        binding.bound <= binding.boxes,
        "a count never exceeds its denominator"
    );
}

/// **A piece that is not its frame suspends the FACE check and nothing else.**
///
/// The owed anchors and the declared class depend on neither the extent nor the
/// contract, so a wrong size must not suppress them — fixing the size would then
/// produce a crop of refusals nobody had been shown, and the place's owed names
/// would have been missing from the binding count while it happened.
#[test]
fn a_wrong_extent_suspends_the_face_check_and_no_other() {
    let tmp = tempdir("no-truncation");
    let d = detailed(&tmp, &["node/exit"]);
    patch_piece(&d, "exit", |v| {
        v["structure"]["size"][0] = serde_json::json!(12);
        v["footprint_class"] = serde_json::json!("expanse");
    });
    patch_detail_plan(&d, |v| {
        v["content"]["details"][0]["anchors"] = serde_json::json!({});
    });
    let (diags, binding) = check_at(&d);
    let found = codes(&diags);
    assert!(found.contains(&"DW0843".to_string()), "{found:?}");
    assert!(
        found.contains(&"DW0845".to_string()),
        "the owed anchor is still asked for: {found:?}"
    );
    assert!(
        found.contains(&"DW0848".to_string()),
        "and the declared class is still judged: {found:?}"
    );
    assert!(
        !found.contains(&"DW0844".to_string()),
        "while the face check is suspended, because its cells come from a frame \
         this piece is not: {found:?}"
    );
    assert_eq!(binding.owed, 1, "and the owed name is IN the denominator");
    assert_eq!(binding.classed, 1, "as is the declared class");
    assert_eq!(
        binding.seams_required, 0,
        "while the suspended check honestly says it examined nothing"
    );
}

// ---------------------------------------------------------------------------
// DW0843 — the piece is not the shape of its allocation
// ---------------------------------------------------------------------------

/// **Undersize refuses exactly as oversize does**, on every axis.
#[test]
fn dw0843_refuses_a_piece_one_cell_off_in_either_direction_on_any_axis() {
    for axis in 0..3 {
        for delta in [1i64, -1] {
            let tmp = tempdir(&format!("dw0843-{axis}-{delta}"));
            let d = detailed(&tmp, &["node/exit"]);
            patch_piece(&d, "exit", |v| {
                let n = v["structure"]["size"][axis].as_i64().unwrap();
                v["structure"]["size"][axis] = serde_json::json!(n + delta);
            });
            let e = check_and_expect(&d, "DW0843");
            assert!(
                e.contains(if delta > 0 { "1 too many" } else { "1 too few" }),
                "the refusal names the direction and the amount: {e}"
            );
            assert!(
                e.contains("undersize refuses exactly as oversize does"),
                "and says why they are the same finding: {e}"
            );
        }
    }
}

