/// **The two observers, proven independent** (spec-0050 §16.7).
///
/// A piece that lies in its metadata — declaring the face while its BYTES seal
/// the way — passes `DW0844`, which reads declarations, and reds on the bytes
/// battery, which reads blocks. Neither could have caught it alone, and that is
/// the whole reason `DW0844` is deliberately redundant with `DW0836`/`DW0838`
/// rather than their replacement.
#[test]
fn a_piece_that_lies_in_its_metadata_passes_dw0844_and_reds_on_bytes() {
    let tmp = tempdir("independent");
    let d = detailed(&tmp, &["node/exit"]);
    // Wall the seam's own cells up in the BYTES, leaving every declaration
    // exactly as it was.
    let c = campaign_at(&d.campaign);
    let a = detail::allocation(&c, &NodeId("node/exit".into())).unwrap();
    let mass = unbound_massing(&c);
    let mut cells = piece_cells(&c, &a, &mass);
    let seam = &a.seams[0];
    for (p, b) in cells.iter_mut() {
        let inside = (0..3).all(|i| {
            i64::from(p[i]) >= seam.cells[0][i].min(seam.cells[1][i])
                && i64::from(p[i]) <= seam.cells[0][i].max(seam.cells[1][i])
        });
        if inside {
            *b = "minecraft:stone_bricks".to_string();
        }
    }
    write_piece(&d.prefabs, "exit", &a, &cells);

    let (diags, _) = check_at(&d);
    assert!(
        errors(&diags).is_empty(),
        "the declaration reader sees nothing wrong — it was not lied to about a \
         declaration: {:?}",
        codes(&diags)
    );

    let (battery, codes) = battery_at(&d);
    assert!(
        codes.iter().any(|c| c == "DW0836" || c == "DW0837"),
        "and the byte reader refuses: {codes:?}"
    );
    assert!(battery.refusal().is_some());
}

