// ---------------------------------------------------------------------------
// DW0821's promotion, in both directions
// ---------------------------------------------------------------------------

/// The fixture declares a vista the derived massing blocks, so the same world is
/// a warning while any box is unbound and a refusal once every node is bound.
/// Nothing is set and nothing is chosen: the severity is computed from the
/// artifact.
#[test]
fn dw0821_is_a_warning_until_every_node_is_bound_and_then_a_refusal() {
    let tmp = tempdir("dw0821-partial");
    let all = every_place();
    let some: Vec<&str> = all[..all.len() - 1].iter().map(String::as_str).collect();
    let partial = detailed(&tmp, &some);
    assert!(!detail::fully_detailed(&campaign_at(&partial.campaign)));
    let (battery, found) = battery_at(&partial);
    assert!(found.iter().any(|c| c == "DW0821"), "{found:?}");
    assert!(
        battery
            .findings
            .iter()
            .any(|(_, d)| d.code == "DW0821" && d.severity == Severity::Warning),
        "one box still massed, so the vista is still the walk sheet's business"
    );

    let tmp = tempdir("dw0821-full");
    let every: Vec<&str> = all.iter().map(String::as_str).collect();
    let full = detailed(&tmp, &every);
    let c = campaign_at(&full.campaign);
    assert!(detail::fully_detailed(&c));
    let (dd, binding) = check_at(&full);
    assert!(
        errors(&dd).is_empty(),
        "a piece cut from the massing of EVERY place satisfies every stage-6 gate — \
         including the hall's hosted stair, the loft's rim over it, the undercroft's \
         climb up through a punched floor, and the way that is not a box with a size \
         class at all: {:?}",
        codes(&dd)
    );
    assert_eq!(
        binding.bound,
        binding.boxes,
        "and every place is bound: {}",
        binding.line()
    );
    assert_eq!(
        binding.seams_required, 14,
        "each of the seven seams answered from both sides"
    );

    let (battery, _) = battery_at(&full);
    let sight: Vec<_> = battery
        .findings
        .iter()
        .filter(|(_, d)| d.code == "DW0821")
        .collect();
    assert_eq!(sight.len(), 1, "the same one vista");
    assert_eq!(
        sight[0].1.severity,
        Severity::Error,
        "and with nothing left to carve it is a refusal"
    );
    let refusal = battery.refusal().expect("which stops the build");
    assert_eq!(
        refusal.1.code,
        "DW0821",
        "and it is the ONLY refusal — the substituted world is otherwise the massed \
         world, over every one of its five places: {:?}",
        battery
            .findings
            .iter()
            .filter(|(_, x)| x.severity == Severity::Error)
            .map(|(_, x)| x.code.clone())
            .collect::<Vec<_>>()
    );
}

// ---------------------------------------------------------------------------
// Traversal equivalence, and determinism
// ---------------------------------------------------------------------------

/// Run the stage-5 battery over the detailed world — the equivalence instrument
/// (spec-0050 §7), unchanged and reused rather than reimplemented.
fn battery_at(d: &Detailed) -> (blockout::Battery, Vec<String>) {
    let c = campaign_at(&d.campaign);
    let reg = PrefabRegistry::load_dir(&d.prefabs).expect("the piece library loads");
    let plan = Plan::build(&c, &reg).expect("the detailed campaign plans");
    let mut structures: BTreeMap<String, Vec<u8>> = BTreeMap::new();
    for area in &plan.areas {
        for piece in &area.pieces {
            for t in &piece.templates {
                if let Ok(bytes) = std::fs::read(d.prefabs.join(&t.structure_file)) {
                    structures.insert(t.structure_file.clone(), bytes);
                }
            }
        }
    }
    let blocks = delvec::compiler::assembled::assembled_blocks(&plan, &structures);
    let battery = blockout::check(&plan, &blocks).expect("a site-plan campaign has a blockout");
    let codes = battery
        .findings
        .iter()
        .map(|(_, d)| d.code.clone())
        .collect();
    (battery, codes)
}

/// **Traversal equivalence, demonstrated as a passing battery rather than
/// asserted** (spec-0050 §16.4): the world with a piece standing where massing
/// stood answers every question the massed world answered, over the same
/// instrument.
#[test]
fn the_stage_five_battery_is_green_over_a_detailed_world() {
    let tmp = tempdir("equivalence");
    let d = detailed(&tmp, &["node/exit"]);
    let (battery, _) = battery_at(&d);
    assert!(
        battery.refusal().is_none(),
        "{:?}",
        battery
            .findings
            .iter()
            .filter(|(_, x)| x.severity == Severity::Error)
            .map(|(_, x)| x.message.clone())
            .collect::<Vec<_>>()
    );
    assert!(
        battery.binding.seams > 0 && battery.binding.nodes == 7,
        "and it bound to the whole map: {}",
        battery.binding.line()
    );
}

/// **Which of a derived area's two anchor producers wins, measured rather than
/// commented.**
///
/// The derivation names `anchor/node-…` at the massing's own footing; a piece
/// standing in that box then owes the same name, and where the piece stands is
/// the truth — so the detail plan's anchors are seated AFTER the derivation's
/// and overwrite them. That is what keeps a campaign's stage-3 vocabulary
/// working across a detailing edit without a quest touching it.
///
/// It is asserted here because the two producers a plan seats through point
/// opposite ways, and only a comment said so. A prefab-placed area is
/// first-wins (`AnchorTable::declare`): a pool can seat one anchor-bearing
/// piece twice, and `DW0498` reports the first carrier. The derived path is
/// last-wins (`AnchorTable::place`). Collapsing them into one rule compiles
/// and leaves every existing test passing, while every detailed place's anchor
/// moves silently back onto the massing — a quest that walks to `node/exit`
/// then walks somewhere nobody authored.
///
/// The control is the second half: the same name on the UNdetailed map. If the
/// two cells were equal the assertion above would hold for the wrong reason,
/// and the test would be green under either rule.
#[test]
fn a_detail_pieces_anchor_overwrites_the_derivations_footing() {
    let tmp = tempdir("anchor-precedence");
    let d = detailed(&tmp, &["node/exit"]);
    let reg = PrefabRegistry::load_dir(&d.prefabs).expect("the piece library loads");
    let key = (
        delvewright_dsl::SITE_AREA.to_string(),
        "anchor/node-exit".to_string(),
    );

    let at = |plan: &Plan<'_>| match plan.anchors.get(&key) {
        Some(delvec::compiler::plan::ResolvedAnchor::Point { pos, .. }) => *pos,
        _ => panic!("a place's own anchor is a cell to stand on"),
    };

    let detailed_c = campaign_at(&d.campaign);
    let detailed_at = at(&Plan::build(&detailed_c, &reg).expect("the detailed campaign plans"));

    let bare_c = campaign_at(&blockout_dir());
    let bare_at = at(&Plan::build(&bare_c, &reg).expect("the undetailed campaign plans"));

    assert_ne!(
        detailed_at, bare_at,
        "the control: if the piece's seat and the massing's footing were the \
         same cell, this test could not tell the two seating rules apart"
    );

    let a = detail::allocation(&detailed_c, &NodeId("node/exit".into()))
        .expect("`node/exit` is a place this map has");
    assert!(
        (0..3).all(|i| {
            i64::from(detailed_at[i]) >= a.world_min[i]
                && i64::from(detailed_at[i]) < a.world_min[i] + a.extent[i]
        }),
        "the resolved cell is inside the piece's own frame, not on the \
         massing's footing: {detailed_at:?} vs the frame at {:?} + {:?}",
        a.world_min,
        a.extent
    );
}

/// **Detailing the ENTRY place moves where the party arrives, and the role is
/// what carries it there.**
///
/// The pair neither change could have tested. The derivation declares
/// `AnchorRole::Entry` on the entry node's anchor (spec-0046) — so `spawn` is a
/// name content may address and not the thing resolution reads — while a
/// `details[]` row on that same place re-binds the name to the piece's own
/// seat. Every other test in this file details `node/exit`, so the one place
/// the two mechanisms meet was never walked.
///
/// What is asserted is the whole chain: the role is declared on a derived map,
/// it still names the owed anchor after detailing, and `Plan::entry_point` —
/// which drives `setworldspawn`, the class-apply teleport, first-join
/// placement and the `dw:cp` seed — lands inside the piece's frame rather than
/// on the massing footing it had before.
#[test]
fn detailing_the_entry_place_moves_where_the_party_arrives() {
    let tmp = tempdir("detailed-entry");
    let d = detailed(&tmp, &["node/landing"]);
    let c = campaign_at(&d.campaign);
    let reg = PrefabRegistry::load_dir(&d.prefabs).expect("the piece library loads");
    let plan = Plan::build(&c, &reg).expect("the detailed campaign plans");
    let area = delvewright_dsl::SITE_AREA.to_string();

    assert_eq!(
        plan.anchors
            .role_name(&area, delvec::compiler::plan::AnchorRole::Entry),
        Some(delvewright_dsl::ENTRY_ANCHOR),
        "a derived map declares what its entry anchor is for, detailed or not"
    );

    let a = detail::allocation(&c, &NodeId("node/landing".into()))
        .expect("`node/landing` is a place this map has");
    assert!(
        a.owed_anchors
            .iter()
            .any(|n| n == delvewright_dsl::ENTRY_ANCHOR),
        "the entry place owes the entry name: {:?}",
        a.owed_anchors
    );

    let at = plan
        .entry_point(&area)
        .expect("the party arrives somewhere");
    assert!(
        (0..3).all(|i| {
            i64::from(at[i]) >= a.world_min[i] && i64::from(at[i]) < a.world_min[i] + a.extent[i]
        }),
        "the party arrives inside the piece standing in the entry place: \
         {at:?} vs the frame at {:?} + {:?}",
        a.world_min,
        a.extent
    );

    let bare_at = Plan::build(&campaign_at(&blockout_dir()), &reg)
        .expect("the undetailed campaign plans")
        .entry_point(&area)
        .expect("the massed map has an entry too");
    assert_ne!(
        at, bare_at,
        "the control: detailing the entry place must actually move the start, \
         or this test would pass over a resolution that never consulted the piece"
    );
}

/// **The derivation stops writing inside a bound frame, and nowhere else.**
///
/// The world a bound campaign masses is the unbound one MINUS exactly the frame,
/// so the fabric split is measured rather than described.
#[test]
fn the_derivation_leaves_a_bound_frame_empty_and_touches_nothing_else() {
    let tmp = tempdir("holes");
    let d = detailed(&tmp, &["node/exit"]);
    let c = campaign_at(&d.campaign);
    let a = detail::allocation(&c, &NodeId("node/exit".into())).unwrap();
    let unbound = massing(&campaign_at(&blockout_dir()));

    let mut reads = delvewright_dsl::metrics::Reads::new();
    let (placement, _) = blockout::derive(&c, &mut reads).expect("the campaign derives");
    let mut bound: BTreeMap<[i64; 3], String> = BTreeMap::new();
    for f in &placement.mass {
        let lo = [
            i64::from(f.from[0]),
            i64::from(f.from[1]),
            i64::from(f.from[2]),
        ];
        let hi = [i64::from(f.to[0]), i64::from(f.to[1]), i64::from(f.to[2])];
        for cell in blockout::cells_of(lo, hi) {
            if f.block == "minecraft:air" {
                bound.remove(&cell);
            } else {
                bound.insert(cell, f.block.clone());
            }
        }
    }

    let inside = |cell: &[i64; 3]| {
        (0..3).all(|i| cell[i] >= a.world_min[i] && cell[i] < a.world_min[i] + a.extent[i])
    };
    let lost: Vec<_> = unbound.keys().filter(|k| !bound.contains_key(*k)).collect();
    assert!(
        !lost.is_empty(),
        "binding a place must actually stop the derivation writing something"
    );
    assert!(
        lost.iter().all(|k| inside(k)),
        "and every cell it stopped writing is inside the frame: {:?}",
        lost.iter().take(4).collect::<Vec<_>>()
    );
    let gained: Vec<_> = bound.keys().filter(|k| !unbound.contains_key(*k)).collect();
    assert!(gained.is_empty(), "and it writes nothing new: {gained:?}");
    for (cell, block) in &bound {
        assert_eq!(
            unbound.get(cell),
            Some(block),
            "and every cell it still writes is the block it always wrote, at {cell:?}"
        );
    }
}

