// ---------------------------------------------------------------------------
// The frame is unauthorable, asserted rather than described
// ---------------------------------------------------------------------------

/// The schema has no spelling for where anything goes, so the whole class of
/// "nudge the frame" edits does not parse. `delvewright_dsl::detailplan` asserts
/// this over the row and the document; here it is asserted end to end, over a
/// real campaign directory, because that is where an author would try it.
#[test]
fn a_detail_plan_cannot_state_a_coordinate() {
    let tmp = tempdir("unauthorable");
    let d = detailed(&tmp, &["node/exit"]);
    for (path, value) in [
        ("min", serde_json::json!([0, 0, 0])),
        ("offset", serde_json::json!([0, 1, 0])),
        ("extent", serde_json::json!([8, 5, 8])),
        ("datum", serde_json::json!("datum/grade")),
    ] {
        patch_detail_plan(&d, |v| {
            v["content"]["details"][0][path] = value;
        });
        let loaded =
            delvec::compiler::load::load_campaign_dir(&d.campaign).expect("still readable");
        let Err(diags) = delvewright_dsl::parse_campaign(&loaded.raw) else {
            panic!("a detail row carrying `{path}` must not parse");
        };
        assert!(
            diags.iter().any(|x| x.code == "DW0100"),
            "the refusal is the schema's: {:?}",
            codes(&diags)
        );
        // Put it back for the next round of the loop.
        patch_detail_plan(&d, |v| {
            v["content"]["details"][0]
                .as_object_mut()
                .unwrap()
                .remove(path);
        });
    }
}

