const BIN: &str = env!("CARGO_BIN_EXE_delvec");

fn delvec(args: &[&str]) -> std::process::Output {
    std::process::Command::new(BIN)
        .args(args)
        .output()
        .expect("run delvec")
}

/// `delvec allocation` hands out the whole of what the plan gives a place, and
/// nothing a piece could give back — there is no coordinate in the SCHEMA, and
/// the world position it prints is stated as a finding aid rather than as an
/// input, because nothing reads it back.
#[test]
fn the_allocation_verb_hands_out_the_frame_the_seams_and_the_owed_names() {
    let tmp = tempdir("allocation-cli");
    let d = detailed(&tmp, &[]);
    let out = delvec(&[
        "--prefabs",
        d.prefabs.to_str().unwrap(),
        "allocation",
        d.campaign.to_str().unwrap(),
        "node/exit",
    ]);
    assert_eq!(
        out.status.code(),
        Some(0),
        "{}",
        String::from_utf8_lossy(&out.stderr)
    );
    let v: serde_json::Value = serde_json::from_slice(&out.stdout).expect("it prints JSON");
    assert_eq!(v["place"], "node/exit");
    // The exit is 8x8 with four of headroom and a lid; it owns its ring on
    // three sides, and the cell beyond its east party plane is the cell's (the
    // seam between them names the cell first), so the frame is 9 wide, the
    // floor course + 4 + the lid tall, and 10 deep (spec-0098 §2).
    assert_eq!(
        v["extent"],
        serde_json::json!([9, 6, 10]),
        "the frame is the place's claim"
    );
    assert_eq!(
        v["seams"][0]["owns_plane"], false,
        "the cell owns the plane"
    );
    assert!(
        v["seams"][0]["form"]
            .as_str()
            .is_some_and(|f| !f.is_empty())
    );
    assert_eq!(v["datum_y"], 1, "and the walk plane is one course up");
    assert_eq!(v["seams"][0]["edge"], "edge/cell-exit");
    assert_eq!(v["seams"][0]["face"], "east");
    assert_eq!(v["seams"][0]["answer_with"], serde_json::json!(["walk"]));
    assert_eq!(v["owed_anchors"], serde_json::json!(["anchor/node-exit"]));
    assert_eq!(
        v["palette"]["role/wall"], "minecraft:stone_bricks",
        "and the whole's vocabulary is handed through, gated by nothing"
    );

    let all = delvec(&[
        "--prefabs",
        d.prefabs.to_str().unwrap(),
        "allocation",
        d.campaign.to_str().unwrap(),
        "--all",
    ]);
    assert_eq!(all.status.code(), Some(0));
    let v: serde_json::Value = serde_json::from_slice(&all.stdout).unwrap();
    assert_eq!(
        v.as_array().unwrap().len(),
        7,
        "one per place, in plan order"
    );
}

